+// ───────────────────────────────────────────────────────────────────────────
+// Training (Master Ledger) — MasterAITrainingLedgerEngine
+// ───────────────────────────────────────────────────────────────────────────
+
+/** Training-run SLO targets — passed inside ingest entries. */
+const slo_targets_schema = z
+  .object({
+    minEvalScore: z.number().finite().describe("Minimum acceptable eval score"),
